import React, { useEffect, useState } from "react";
import axios from "axios";
import "./RiverDashboard.css"; 

// The endpoint provided in your views.py
const DEBUG_API = "http://127.0.0.1:8000/api/weather/debug-read-s3";

const RiverDashboard = () => {
  // 1. State for numerical forecast
  const [forecastData, setForecastData] = useState([]);
  // 2. State for Explainable AI (LIME) text
  const [limeData, setLimeData] = useState([]); 
  
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [lastUpdated, setLastUpdated] = useState("");

  // Helper to determine status color based on water level
  const getStatus = (level) => {
    const val = parseFloat(level);
    if (val < 5.5) return { label: "Normal", class: "alert-normal", color: "#00b894" }; // GREEN
    if (val < 6.0) return { label: "Caution", class: "alert-watch", color: "#fdcb6e" }; // ORANGE
    return { label: "Warning", class: "alert-critical", color: "#ff6b6b" }; // RED
  };

  useEffect(() => {
    // Function to fetch the numerical forecast CSV
    const fetchForecast = async () => {
      try {
        const response = await axios.get(DEBUG_API, {
          params: { file: "forecast_output.csv" },
        });

        if (response.data.status === "success") {
          const rawLines = response.data.preview;
          const parsedData = rawLines
            .slice(1) // Remove header
            .map((line) => {
              const cols = line.split(",");
              const level = cols[cols.length - 1]?.trim(); 
              return {
                level: parseFloat(level).toFixed(2),
                status: getStatus(level),
              };
            })
            .filter((item) => !isNaN(item.level));

          setForecastData(parsedData);
          
          const now = new Date();
          const datePart = `${now.getDate()}/${now.getMonth() + 1}/${now.getFullYear()}`;
          const timePart = now.toLocaleTimeString("en-US");
          setLastUpdated(`${datePart}, ${timePart}`);
        }
      } catch (err) {
        console.error("Forecast API error:", err);
        setError("Failed to fetch forecast data");
      }
    };

    // Function to fetch the Explainable AI Text File
    const fetchLimeInsights = async () => {
      try {
        const response = await axios.get(DEBUG_API, {
          params: { file: "lime_short_sentences_and_labels.txt" },
        });

        if (response.data.status === "success") {
          setLimeData(response.data.preview); 
        }
      } catch (err) {
        console.error("LIME API error:", err);
      }
    };

    // Execute both fetches
    const loadAllData = async () => {
      setLoading(true);
      await Promise.all([fetchForecast(), fetchLimeInsights()]);
      setLoading(false);
    };

    loadAllData();
  }, []);

  if (loading) {
    return (
      <div className="dashboard-wrapper loading-container">
        <div className="spinner"></div>
        <p>Loading AI Forecasts...</p>
      </div>
    );
  }

  if (error && forecastData.length === 0) {
    return (
      <div className="dashboard-wrapper loading-container">
        <div className="error-msg">
          <h3>Connection Error</h3>
          <p>{error}</p>
        </div>
      </div>
    );
  }

  // Safe access for current level display
  const nextHour = forecastData[0] || { level: "--", status: getStatus(0) };
  const currentLevel = (parseFloat(nextHour.level) - 0.17).toFixed(2); 

  return (
    <div className="dashboard-wrapper">
      <div className="dashboard">
        {/* Header */}
        <div className="header">
          <h1>Kalady Periyar River Water Level</h1>
          <p>Real-time monitoring with 6-hour AI forecast</p>
        </div>

        {/* Alert Banner */}
        <div className="alert-banner watch">
          <i className="fas fa-exclamation-triangle"></i>
          <span>
            Flood Monitoring & Early Warning System - Water levels can rise
            rapidly during heavy rainfall. Stay alert.
          </span>
        </div>

        {/* Status Bar */}
        <div className="status-bar">
          <div className="status-indicator">
            <div className="status-dot"></div>
            <span>System Active</span>
          </div>
          <span className="last-update">Updated: {lastUpdated}</span>
        </div>

        {/* Metrics Grid */}
        <div className="metrics-grid">
          {/* Current Level */}
          <div className="metric-card water-level">
            <div className="metric-header">
              <span className="metric-title">Current Water Level</span>
              <i className="fas fa-water metric-icon"></i>
            </div>
            <div className="metric-value">
              {currentLevel} <span className="metric-unit">m</span>
            </div>
            <div className="metric-timestamp">Sensor ID: WL-2024-KLD</div>
          </div>

          {/* Next Hour Forecast */}
          <div className={`metric-card forecast ${nextHour.status.class}`}>
            <div className="metric-header">
              <span className="metric-title">Next Hour Forecast</span>
              <i className="fas fa-clock metric-icon"></i>
            </div>
            <div className="metric-value">
              {nextHour.level} <span className="metric-unit">m</span>
            </div>
            <div className="metric-timestamp">
              Status: {nextHour.status.label}
            </div>
          </div>
        </div>

        {/* 6-Hour Forecast Section */}
        <div className="forecast-section">
          <div className="forecast-header">
            <i className="fas fa-chart-line"></i>
            <span className="forecast-title">6-Hour Water Level Forecast</span>
          </div>
          <div className="forecast-values">
            {forecastData.slice(0, 6).map((data, index) => (
              <div key={index} className="forecast-item">
                <div className="forecast-time">H+{index + 1}</div>
                <div className="forecast-value">{data.level} m</div>
                <div
                  style={{
                    color: data.status.color,
                    fontWeight: "bold",
                    marginTop: "5px",
                    fontSize: "0.85em",
                  }}
                >
                  {data.status.label}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* --- EXPLAINABLE AI INSIGHTS --- */}
        <div className="forecast-section" style={{ marginTop: "30px" }}>
          <div className="forecast-header">
            <i className="fas fa-brain"></i>
            <span className="forecast-title">Explainable AI Insights</span>
          </div>
          
          {limeData.length > 0 ? (
            limeData.slice(0, 6).map((line, index) => {
              // 1. Get the forecast data for this specific hour (to find the color)
              const forecastItem = forecastData[index];
              const statusColor = forecastItem ? forecastItem.status.color : "#74b9ff";
              const statusLabel = forecastItem ? forecastItem.status.label : "Info";

              return (
                <div 
                  key={index} 
                  className="lime-item" 
                  style={{ 
                    borderLeft: `5px solid ${statusColor}`,
                    background: `linear-gradient(90deg, ${statusColor}15, transparent)` // Light tint background
                  }}
                >
                  <div style={{ fontWeight: "bold", minWidth: "40px", color: "#2c3e50" }}>
                    H+{index + 1}
                  </div>
                  
                  {/* Status Badge - Colored Background with White Text */}
                  <span
                    style={{
                      backgroundColor: statusColor,
                      color: "white",
                      padding: "2px 8px",
                      borderRadius: "4px",
                      fontSize: "0.8em",
                      marginRight: "10px",
                      fontWeight: "bold",
                      textTransform: "uppercase"
                    }}
                  >
                    {statusLabel}
                  </span>

                  {/* The Explanation Text */}
                  <p style={{ margin: 0, fontSize: "0.95em", color: "#34495e" }}>
                    {line}
                  </p>
                </div>
              );
            })
          ) : (
            <div style={{ padding: "20px", textAlign: "center", color: "#7f8c8d" }}>
              No AI insights currently available.
            </div>
          )}
        </div>

      </div>
    </div>
  );
};

export default RiverDashboard;
